// Single source of truth for soil-layer colours. Both the map fill (getSoilStyle in
// app/src/components/LLMap/index.jsx) and every legend swatch (the dynamic
// buildSoilLegendEntries legend plus the static pre-load SOIL_LEGEND in
// app/src/data/layers.js) must resolve their colours through this module -- never
// reintroduce a locally-declared soil hex anywhere else.
//
// This file is hand-authored. Unlike its siblings land_cover_legend.js and
// climate_legend.js, it is NOT generated by data-pipeline/sync.py -- no Python file
// contains any soil hex, and running `python sync.py` will never overwrite this file.
//
// Pure, dependency-free ES module (no React, no Leaflet) so it stays importable by
// plain `node`, mirroring the app/src/lib/chartSeries.js precedent -- this lets
// app/scripts/check_soil_palette.mjs import it directly for the automated
// distinctness gate.

// Tier 1: the 12 stable, semantically named soil groups. Every class is separated on
// both hue and lightness (see 260804-acf-PLAN.md's <palette_spec> for the full design
// rationale and measured CIELAB figures).
export const SOIL_GROUP_COLORS = Object.freeze({
  'brown-soils': '#8C4A16',
  luvisols: '#E69F00',
  'ah-c-soils': '#EFE0A2',
  'gley-soils': '#0072B2',
  'stagnic-soils': '#A97FCB',
  fens: '#41382B',
  'alluvial-soils': '#009E73',
  'initial-soils': '#C9A063',
  podzols: '#8C8FA8',
  pelosols: '#B5453C',
  'raised-bogs': '#6B4B7A',
  'sealed-surfaces': '#4E545C',
})

// Tier 2: fallback palette for unnamed / future keys (the long free-text-derived
// anthropogenic slugs). Index order is significant -- it is what the FNV-1a hash
// below indexes into. Keep exactly this order.
export const SOIL_FALLBACK_PALETTE = Object.freeze([
  '#6E4B4B',
  '#7F9E5C',
  '#8E6E4E',
  '#D4A6C8',
  '#4F6B4A',
])

// Tier 3: non-soil feature kinds and strokes.
export const SOIL_WATER_FILL = '#88BFD9'
export const SOIL_WATER_STROKE = '#4F89A3'
export const SOIL_SPECIAL_FILL = '#C9C9C9'
export const SOIL_SPECIAL_STROKE = '#8A8A8A'
export const SOIL_UNIT_STROKE = '#3F3F3F'

// FNV-1a hash (32-bit), replacing the previous `acc * 31 + charCode` reduce which
// distributed poorly across long slug keys -- three of the four unnamed anthropogenic
// keys landed in the same bucket. Offset basis 0x811c9dc5, prime multiply via
// Math.imul, >>> 0 after each step and on the final result.
function fnv1aHash(value) {
  let hash = 0x811c9dc5
  const str = String(value)
  for (let i = 0; i < str.length; i += 1) {
    hash ^= str.charCodeAt(i)
    hash = Math.imul(hash, 0x01000193)
    hash = hash >>> 0
  }
  return hash >>> 0
}

// Resolves a soil group key to its colour. Known named groups (Tier 1) return their
// exact colour; anything else is indexed into the Tier 2 fallback palette by an FNV-1a
// hash. Uses an own-property check so a crafted key such as `constructor` or
// `__proto__` cannot resolve to a prototype member (T-acf-01).
export function getSoilColor(groupKey) {
  if (Object.prototype.hasOwnProperty.call(SOIL_GROUP_COLORS, groupKey)) {
    return SOIL_GROUP_COLORS[groupKey]
  }
  const index = fnv1aHash(groupKey) % SOIL_FALLBACK_PALETTE.length
  return SOIL_FALLBACK_PALETTE[index]
}
